# No 4-regular circulant with girth 6 on 28 vertices. Try 5 or 6-regular circulants.
# For 5 generators: a,-a, b,-b, n/2 if n even (self-inverse)
from collections import deque

def circulant_girth(n, gens):
    adj = [[] for _ in range(n)]
    for v in range(n):
        for g in gens:
            u = (v+g) % n
            if u != v:
                adj[v].append(u)
    # make unique
    for i in range(n):
        adj[i] = list(set(adj[i]))
    g_min = float('inf')
    s = 0
    dist = {s:0}
    parent = {s: -1}
    q = deque([s])
    while q:
        u = q.popleft()
        for v in adj[u]:
            if v not in dist:
                dist[v] = dist[u]+1
                parent[v] = u
                q.append(v)
            elif parent[u] != v:
                c = dist[u]+dist[v]+1
                if c < g_min: g_min = c
    return g_min, adj

